<?php require_once 'config/database.php';require_once 'includes/functions.php';$pageTitle='Login';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$em=trim($_POST['email']??'');$pw=$_POST['password']??'';$s=$pdo->prepare("SELECT * FROM users WHERE email=? AND role='customer' LIMIT 1");$s->execute([$em]);$u=$s->fetch();if($u&&password_verify($pw,$u['password'])){$_SESSION['user']=$u;load_user_lists($pdo);go('index.php');}$err='Invalid customer email or password.';}require 'includes/header.php';?><section class="section"><div class="container formwrap"><div class="eyebrow">Customer Area</div><h1>Login</h1><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form class="panel" method="post"><div class="group"><label>Email</label><input class="input" type="email" name="email" required></div><div class="group"><label>Password</label><input class="input" type="password" name="password" required></div><button class="btn">Login</button><p style="color:#aaa">Admin? <a href="admin/login.php">Use Admin Login</a></p></form></div></section><?php require 'includes/footer.php';?>
